// Fixture batch 101: curvature derivatives, internal tolerances, a B-spline approximation. Generated by tools/fixtures/gen-batch-101.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function roundAll(a is array) returns array
{
    return mapArray(a, function(x) { return x is number ? roundToPrecision(x, 6) : (x is array ? roundAll(x) : x); });
}

// A matrix with units of 1/length², in 1/mm², rounded.
function perSquareMillimetre(m is MatrixWithUnits) returns array
{
    return mapArray([0, 1, 2], function(i) { return mapArray([0, 1, 2], function(j) { return roundToPrecision(m.value[i][j] * 1e-6, 9); }); });
}

// The derivative of a face's second fundamental form at a parameter along its tangent plane's x and y axes, in
// 1/mm².
function derivatives(context is Context, face is Query, parameter is Vector) returns array
{
    const plane = evFaceTangentPlane(context, { "face" : face, "parameter" : parameter });
    return mapArray([plane.x, yAxis(plane)], function(direction) {
            const m = evFaceCurvatureDerivative(context, { "face" : face, "parameter" : parameter, "direction" : direction });
            return { "direction" : roundAll([direction[0], direction[1], direction[2]]), "matrix" : perSquareMillimetre(m) };
        });
}

// curvature: a cylinder's (radius 10) derivatives at two parameters
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    return { "a" : derivatives(context, qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER), vector(0.25, 0.5)), "b" : derivatives(context, qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER), vector(0.1, 0.3)) };
}

// curvature: a torus's (radii 20 and 5) derivatives at a parameter
export function c002(context is Context, id is Id)
{
    const p1 = newSketchOnPlane(context, id + "p1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(p1, "c1", { "center" : vector(20, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(p1);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "p1"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    return { "a" : derivatives(context, qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.TORUS), vector(0.3, 0.2)) };
}

