// curvature: a cone frustum's (radius 10 at z = 0 to 5 at z = 20) derivatives at a parameter
export function c004(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(10, 0) * millimeter, "end" : vector(5, 20) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(5, 20) * millimeter, "end" : vector(0, 20) * millimeter });
    skLineSegment(s1, "l4", { "start" : vector(0, 20) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : sketchEntityQuery(id + "s1", EntityType.EDGE, "l4"), "fullRevolve" : true });
    return { "a" : derivatives(context, qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CONE), vector(0.3, 0.5)) };
}

// curvature: a cylinder's derivative along a direction leaning half out of its tangent plane
export function c005(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const plane = evFaceTangentPlane(context, { "face" : qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER), "parameter" : vector(0.1, 0.3) });
    const m = evFaceCurvatureDerivative(context, { "face" : qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER), "parameter" : vector(0.1, 0.3), "direction" : normalize(yAxis(plane) + 0.5 * plane.normal) });
    return { "matrix" : perSquareMillimetre(m) };
}

