    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    const s = evApproximateBSplineSurface(context, { "face" : qGeometry(qOwnedByBody(qCreatedBy(id + "base", EntityType.BODY), EntityType.FACE), GeometryType.CYLINDER) }).bSplineSurface;
    return { "poles" : mapArray(s.controlPoints, function(row) { return mapArray(row, function(p) { return roundAll([p[0] / millimeter, p[1] / millimeter, p[2] / millimeter]); }); }), "weights" : roundAll(s.weights) };
